import ccxt.async_support as ccxt  # noqa: F402

def test_mod_pow():
    exchange = ccxt.Exchange({
        'id': 'sampleexchange',
    })
    # intToBase16 emits uppercase hex in some target languages, assign before toLowerCase (php transpiler)
    # small values
    small = exchange.mod_pow(exchange.convert_to_big_int('4'), exchange.convert_to_big_int('13'), exchange.convert_to_big_int('497'))
    small_hex_raw = exchange.int_to_base16(small)
    small_hex = small_hex_raw.lower()
    assert small_hex == '1bd', 'modPow small failed, expected: 1bd, got: ' + small_hex
    # results above 2^64 must survive intToBase16 (the interactivebrokers diffie-hellman challenge is 2048-bit)
    # 2 ^ 100 mod (2 ^ 127 - 1) = 2 ^ 100
    modulus = exchange.convert_to_big_int('0x7fffffffffffffffffffffffffffffff')
    big = exchange.mod_pow(exchange.convert_to_big_int('2'), exchange.convert_to_big_int('100'), modulus)
    big_hex_raw = exchange.int_to_base16(big)
    big_hex = big_hex_raw.lower()
    assert big_hex == '10000000000000000000000000', 'modPow big failed, expected: 10000000000000000000000000, got: ' + big_hex
    # 0xffffffffffffffffffff ^ 3 mod (2 ^ 127 - 1)
    base = exchange.convert_to_big_int('0xffffffffffffffffffff')
    cubed = exchange.mod_pow(base, exchange.convert_to_big_int('3'), modulus)
    cubed_hex_raw = exchange.int_to_base16(cubed)
    cubed_hex = cubed_hex_raw.lower()
    assert cubed_hex == '200000002fffffffffff9ffffffff', 'modPow cubed failed, expected: 200000002fffffffffff9ffffffff, got: ' + cubed_hex
